pipeline {
    agent any

    triggers {
        // Poll SCM every 15 minutes for changes
        pollSCM('H/15 * * * *')
    }

    environment {
        // Define any environment variables needed
        BUILD_NUMBER = env.BUILD_NUMBER
        GIT_BRANCH = env.GIT_BRANCH
    }

    stages {
        stage('Checkout') {
            steps {
                script {
                    echo "Checking out source code..."
                    checkout scm
                }
            }
        }

        stage('Build') {
            steps {
                script {
                    echo "Starting build..."
                    // Replace with actual build command
                    sh 'make build || echo "Build step skipped or placeholder"'
                }
            }
        }

        stage('Test') {
            steps {
                script {
                    echo "Running tests..."
                    // Replace with actual test command
                    sh 'make test || echo "Test step skipped or placeholder"'
                }
            }
            post {
                always {
                    // Archive test results if available
                    junit 'test-reports/*.xml', allowEmptyResults: true
                }
            }
        }

        stage('Deploy') {
            steps {
                script {
                    echo "Deploying application..."
                    // Replace with actual deploy command or script
                    sh 'make deploy || echo "Deploy step skipped or placeholder"'
                }
            }
        }
    }

    post {
        success {
            echo 'Pipeline completed successfully.'
            // Optionally notify team
        }
        failure {
            echo 'Pipeline failed.'
            // Optionally send alerts
        }
        always {
            // Clean up or notify regardless of outcome
            cleanWs()  // Requires Workspace Cleanup Plugin
        }
    }
}

